sys_script_include.script:
var IntegrationEventPublisher = Class.create();
IntegrationEventPublisher.prototype = {

    initialize: function () {
        this.serializer = new AggregateSerializer();
    },

    // Outbox. opts: { eventType, aggregate, table, sysId, system, correlationId, payload }
    // payload defaults to the canonical aggregate snapshot when the aggregate is serialisable.
    publish: function (opts) {
        var payload = opts.payload;
        if (payload === undefined && opts.aggregate && AggregateSerializer.TREES[opts.aggregate])
            payload = this.serializer.serialize(opts.aggregate, opts.sysId);
        return this._write(Constants.CHOICE.DIRECTION.OUTBOUND, opts, payload);
    },

    // Inbox with idempotency: the same correlation id + payload hash is recorded
    // once; a replay returns the existing event marked as already handled.
    receive: function (opts) {
        var body = typeof opts.payload === 'string' ? opts.payload : JSON.stringify(opts.payload || {});
        var hash = this.hash(body);
        if (opts.correlationId) {
            var dupe = new GlideRecord(Constants.TABLE.INTEGRATION_EVENT);
            dupe.addQuery('direction', Constants.CHOICE.DIRECTION.INBOUND);
            dupe.addQuery('correlation_id', opts.correlationId);
            dupe.addQuery('payload_hash', hash);
            dupe.setLimit(1);
            dupe.query();
            if (dupe.next())
                return { sys_id: dupe.getUniqueValue(), duplicate: true };
        }
        return { sys_id: this._write(Constants.CHOICE.DIRECTION.INBOUND, opts, body), duplicate: false };
    },

    markProcessed: function (eventId, ok, error) {
        var gr = new GlideRecord(Constants.TABLE.INTEGRATION_EVENT);
        if (!gr.get(eventId))
            return false;
        gr.setValue('status', ok ? Constants.CHOICE.INTEGRATION_EVENT_STATUS.PROCESSED : Constants.CHOICE.INTEGRATION_EVENT_STATUS.FAILED);
        gr.setValue('attempts', (parseInt(gr.getValue('attempts'), 10) || 0) + 1);
        gr.setValue('last_error', error ? String(error).substring(0, 4000) : '');
        gr.setValue('processed_on', new GlideDateTime());
        gr.update();
        return true;
    },

    hash: function (text) {
        return new GlideDigest().getSHA256Hex(String(text));
    },

    _write: function (direction, opts, payload) {
        var body = typeof payload === 'string' ? payload : JSON.stringify(payload === undefined ? {} : payload);
        var gr = new GlideRecord(Constants.TABLE.INTEGRATION_EVENT);
        gr.initialize();
        gr.setValue('direction', direction);
        gr.setValue('event_type', opts.eventType);
        if (opts.aggregate)
            gr.setValue('aggregate', opts.aggregate === 'policy_version' ? Constants.CHOICE.INTEGRATION_AGGREGATE.POLICY : opts.aggregate);
        gr.setValue('table_name', opts.table || '');
        gr.setValue('record_sys_id', opts.sysId || '');
        if (opts.system)
            gr.setValue('integration_system', opts.system);
        gr.setValue('correlation_id', opts.correlationId || gs.generateGUID());
        gr.setValue('payload', body);
        gr.setValue('payload_hash', this.hash(body));
        gr.setValue('status', Constants.CHOICE.INTEGRATION_EVENT_STATUS.PENDING);
        gr.setValue('attempts', 0);
        return gr.insert();
    },

    type: 'IntegrationEventPublisher'
};
